WITH flattened AS (SELECT id, effective_from, tier_value FROM price_tiers LATERAL VIEW EXPLODE(tier_limits) li AS tier_value) SELECT CASE WHEN tier_value >= 71 THEN 'HIGH' ELSE 'LOW' END AS tier_value_tier, DATE_TRUNC('WEEK', effective_from) AS week_start, DATE_TRUNC('MONTH', effective_from) AS activity_month, COUNT(*) AS cnt, COUNT(*) AS cnt_2, COUNT(*) AS num_rows FROM flattened GROUP BY CASE WHEN tier_value >= 71 THEN 'HIGH' ELSE 'LOW' END, DATE_TRUNC('WEEK', effective_from), DATE_TRUNC('MONTH', effective_from) HAVING num_rows > 1 ORDER BY cnt DESC;
